function Projects() {
  const [repos, setRepos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [search, setSearch] = useState('');
  useEffect(() => {
    fetch('https://api.github.com/users/Dharmikvaghani/repos')
      .then(res => res.json())
      .then(data => { setRepos(data); setLoading(false); })
      .catch(err => { console.error(err); setLoading(false); });
  }, []);
  const filtered = repos.filter(r => r.name.toLowerCase().includes(search.toLowerCase()));
  return (
    <div className="projects-container">
      <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Filter..." />
      {loading ? <Skeleton /> : filtered.map(r => <RepoCard key={r.id} repo={r} />)}
    </div>
  );
}
